          {HEADLINE.nAmericaGrowthContribPct}% of growth. Toggle{" "}
          <strong className="text-white">Regions</strong>,{" "}
          <strong className="text-white">Scatter</strong>,{" "}
          <strong className="text-white">Trade</strong>, and{" "}
