"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ASIA_SPLIT,
  COUNTRY_GEO,
  HEADLINE,
  PRICE_REGIMES,
  REGION_METERS,
  REGION_SHARES,
  SOURCE_NOTE,
  TRADE_CORRIDORS,
  countryScatter,
  fmtPct,
  regionMetricValue,
} from "@/data/macro-growth-trade-geography-2026-data";

// viz-types: region bars+pie, growth??CPI scatter, trade corridor bars+donut, Asia split stacked, price-regime pie+bars, meter compare | layout: default

type ViewId = "regions" | "scatter" | "trade" | "prices";
type RegionMetric = "ppp" | "growth" | "trade" | "export";
type AsiaLens = "growth" | "ppp" | "export";
type ScatterFilter = "all" | "Asia" | "North America" | "Europe" | "Latin America" | "MENA";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
